import sys

input = sys.stdin.readline

class RookGame:
    def __init__(self, N, K, P):
        self.N = N
        self.K = K
        self.P = P
        self.row_rooks = {}
        self.col_rooks = {}
        self.rook_pos = {}
        self.rook_power = {}
        self.attacked = 0

    def add_rook(self, r, c, x):
        self.rook_pos[(r, c)] = x
        self.rook_power[(r, c)] = x

        if r not in self.row_rooks:
            self.row_rooks[r] = set()
        self.row_rooks[r].add((r, c))

        if c not in self.col_rooks:
            self.col_rooks[c] = set()
        self.col_rooks[c].add((r, c))

    def remove_rook(self, r, c):
        x = self.rook_pos.pop((r, c))
        self.row_rooks[r].remove((r, c))
        self.col_rooks[c].remove((r, c))

        if not self.row_rooks[r]:
            del self.row_rooks[r]
        if not self.col_rooks[c]:
            del self.col_rooks[c]

        return x

    def move_rook(self, r1, c1, r2, c2):
        x = self.remove_rook(r1, c1)
        self.add_rook(r2, c2, x)

    def count_attacked(self):
        rows_with_rooks = len(self.row_rooks)
        cols_with_rooks = len(self.col_rooks)

        attacked_rows = rows_with_rooks * self.N
        attacked_cols = cols_with_rooks * self.N

        intersections = 0
        for (r, c) in self.rook_pos:
            if r in self.row_rooks and c in self.col_rooks:
                intersections += 1

        return attacked_rows + attacked_cols - intersections

    def solve(self):
        results = []

        for _ in range(self.K):
            r, c, x = map(int, input().split())
            self.add_rook(r, c, x)

        for _ in range(self.P):
            r1, c1, r2, c2 = map(int, input().split())
            self.move_rook(r1, c1, r2, c2)
            results.append(self.count_attacked())

        return results

def main():
    N, K, P = map(int, input().split())
    game = RookGame(N, K, P)
    results = game.solve()
    print('\n'.join(map(str, results)))

if __name__ == "__main__":
    main()

