import sys

input = sys.stdin.readline

class RookGame:
    def __init__(self, N, K, P):
        self.N = N
        self.K = K
        self.P = P
        self.row_xor = {}
        self.col_xor = {}
        self.rook_pos = {}
        self.rook_power = {}
        self.total_attacked = 0
        self.total_cells = N * N

    def add_rook(self, r, c, x):
        self.rook_pos[(r, c)] = x
        self.rook_power[(r, c)] = x

        # Update row and column XORs
        if r not in self.row_xor:
            self.row_xor[r] = 0
        if c not in self.col_xor:
            self.col_xor[c] = 0

        self.row_xor[r] ^= x
        self.col_xor[c] ^= x

    def remove_rook(self, r, c):
        x = self.rook_power[(r, c)]

        # Update row and column XORs
        self.row_xor[r] ^= x
        self.col_xor[c] ^= x

        # Clean up if row/column becomes empty
        if self.row_xor[r] == 0:
            del self.row_xor[r]
        if self.col_xor[c] == 0:
            del self.col_xor[c]

        del self.rook_pos[(r, c)]
        del self.rook_power[(r, c)]

    def move_rook(self, r1, c1, r2, c2):
        # Remove from old position
        x = self.rook_power[(r1, c1)]
        self.remove_rook(r1, c1)

        # Add to new position
        self.add_rook(r2, c2, x)

    def count_attacked(self):
        # Count cells attacked by rows
        row_attacked = 0
        for r, xor_val in self.row_xor.items():
            if xor_val > 0:
                row_attacked += self.N - 1  # All cells in row except rook's own

        # Count cells attacked by columns
        col_attacked = 0
        for c, xor_val in self.col_xor.items():
            if xor_val > 0:
                col_attacked += self.N - 1  # All cells in column except rook's own

        # Subtract double-counted intersections
        intersections = 0
        for (r, c), x in self.rook_pos.items():
            row_val = self.row_xor.get(r, 0)
            col_val = self.col_xor.get(c, 0)

            # Cell is attacked if row XOR > 0 or column XOR > 0
            if row_val > 0 or col_val > 0:
                intersections += 1

        # Total attacked cells
        total = row_attacked + col_attacked - intersections
        return total

    def solve(self):
        # Read initial rooks
        for _ in range(self.K):
            r, c, x = map(int, input().split())
            self.add_rook(r, c, x)

        results = []

        # Process moves
        for _ in range(self.P):
            r1, c1, r2, c2 = map(int, input().split())
            self.move_rook(r1, c1, r2, c2)
            results.append(self.count_attacked())

        return results

def main():
    N, K, P = map(int, input().split())
    game = RookGame(N, K, P)
    results = game.solve()

    for res in results:
        print(res)

if __name__ == "__main__":
    main()

