import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    c = list(map(int, data[1:1+n]))

    # Initialize result string with 'a'
    res = ['a'] * n

    # Process from longest substring length to shortest
    for length in range(n, 0, -1):
        count = c[length-1]
        if count == 0:
            continue

        # Find positions where we can place blocks of identical letters
        pos = 0
        while count > 0 and pos < n:
            # Skip if this position already has a different letter
            if pos > 0 and res[pos] != res[pos-1]:
                pos += 1
                continue

            # Check if we can place a block starting at pos
            can_place = True
            # Ensure we don't go out of bounds
            if pos + length > n:
                pos += 1
                continue

            # Check if positions in [pos, pos+length) are either 'a' or same as previous
            for i in range(pos, pos+length):
                if i > 0 and res[i] != res[i-1]:
                    can_place = False
                    break

            if can_place:
                # Place block: assign a new letter (increment from previous)
                if pos == 0:
                    new_char = 'b'
                else:
                    new_char = chr(ord(res[pos-1]) + 1)
                    if new_char > 'z':
                        new_char = 'a'

                for i in range(pos, pos+length):
                    res[i] = new_char
                count -= 1
                pos += length
            else:
                pos += 1

    # Fill remaining positions with distinct letters
    for i in range(n):
        if res[i] == 'a':
            # Use a letter that hasn't been used recently
            if i == 0:
                res[i] = 'a'
            else:
                # Use next available letter
                prev = ord(res[i-1])
                next_char = chr(prev + 1) if prev < ord('z') else 'a'
                res[i] = next_char

    print(''.join(res))

if __name__ == "__main__":
    solve()

