def count_distinct_prime_factors(n):
    """Return the number of distinct prime factors of n."""
    count = 0
    i = 2
    while i * i <= n:
        if n % i == 0:
            count += 1
            while n % i == 0:
                n //= i
        i += 1
    if n > 1:
        count += 1
    return count

def main():
    a = int(input().strip())
    result = count_distinct_prime_factors(a)
    print(result)

if __name__ == "__main__":
    main()

