import sys

sys.setrecursionlimit(400000)

class Node:
    __slots__ = ('value', 'left', 'right', 'size')
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None
        self.size = 1

def insert(root, value, depth, total_depth):
    if root is None:
        return Node(value), depth

    root.size += 1
    if value < root.value:
        if root.left is None:
            root.left = Node(value)
            return root, depth + 1
        else:
            root.left, new_depth = insert(root.left, value, depth + 1, total_depth)
            return root, new_depth
    else:
        if root.right is None:
            root.right = Node(value)
            return root, depth + 1
        else:
            root.right, new_depth = insert(root.right, value, depth + 1, total_depth)
            return root, new_depth

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    values = list(map(int, data[1:1+n]))

    root = None
    total_depth = 0
    results = []

    for value in values:
        if root is None:
            root = Node(value)
            depth = 0
        else:
            root, depth = insert(root, value, 0, total_depth)
        total_depth += depth
        results.append(str(total_depth))

    sys.stdout.write('\n'.join(results))

if __name__ == "__main__":
