    for u1 in range(1, 10001):
        for u2 in range(u1 + 1, 10001):
            # For each front pair, compute all possible gear ratios
            possible_ratios = set()
            for u in (u1, u2):
                for v in range(1, 10001):
                    g = math.gcd(u, v)
                    possible_ratios.add((u // g, v // g))
                    if len(possible_ratios) >= 12:
                        break
                if len(possible_ratios) >= 12:
                    break

            # Check if all required ratios are in possible_ratios
            if all(r in possible_ratios for r in ratios):
                # Now find rear sprockets that work with this front pair
                # We need 6 distinct rear sprockets v1 < v2 < ... < v6
                # Each ratio (n/d) must equal u/v for some u in {u1,u2}, v in {v1..v6}
                # So for each ratio, v = u * d / n must be integer and ≤10000
