pairs = []
for b in range(1, k + 1):
    for g in range(1, k + 1):
        if b != g:
            pairs.append((b, g))

# We'll output the first n pairs from this list
# But we need to ensure consecutive pairs differ in both components
# We can organize the pairs in a specific order to guarantee this

# Create a sequence where consecutive pairs differ in both components
# One simple approach: alternate between two patterns
result = []

# If k >= 2, we can create a sequence like:
# (1,2), (2,1), (1,3), (3,1), (2,3), (3,2), ...
# This ensures all constraints are satisfied

if k == 2:
    # Special case: only 2 colors, only 2 possible pairs
    if n > 2:
        print("NO")
        sys.exit(0)
    result = [(1, 2), (2, 1)][:n]
else:
    # General case: k >= 3
    # We'll generate pairs in a systematic way
    # Create two sequences that cycle through colors

    # First, generate all pairs where b < g
    increasing = []
    for b in range(1, k + 1):
        for g in range(b + 1, k + 1):
            increasing.append((b, g))

    # Then generate all pairs where b > g
    decreasing = []
    for g in range(1, k + 1):
        for b in range(g + 1, k + 1):
            decreasing.append((b, g))

    # Interleave them to ensure consecutive pairs differ
    result = []
    idx1, idx2 = 0, 0

    while len(result) < n:
        if idx1 < len(increasing):
            result.append(increasing[idx1])
            idx1 += 1
            if len(result) >= n:
                break

        if idx2 < len(decreasing):
            result.append(decreasing[idx2])
            idx2 += 1
            if len(result) >= n:
                break

    # If we still need more pairs, continue cycling
    if len(result) < n:
        # Start again from the beginning
        remaining = n - len(result)
        for i in range(remaining):
            if i % 2 == 0:
                result.append(increasing[i % len(increasing)])
            else:
                result.append(decreasing[i % len(decreasing)])

# Verify all constraints (for safety)
def verify(result):
    if len(result) != n:
        return False

    seen = set()
    for i, (b, g) in enumerate(result):
        # Check colors are in range
        if not (1 <= b <= k and 1 <= g <= k):
            return False
        # Check man and woman have different colors
        if b == g:
            return False
        # Check no duplicate pairs
        if (b, g) in seen:
            return False
        seen.add((b, g))

        # Check consecutive pairs differ
        if i > 0:
            prev_b, prev_g = result[i-1]
            if b == prev_b or g == prev_g:
                return False
    return True

# Output the result
for b, g in result:
    print(f"{b} {g}")

