import sys
import math

# Precompute primes up to sqrt(1e6) = 1000
MAX_VAL = 1000000
MAX_PRIME = 1000
is_prime = [True] * (MAX_PRIME + 1)
is_prime[0] = is_prime[1] = False
primes = []
for i in range(2, MAX_PRIME + 1):
    if is_prime[i]:
        primes.append(i)
        for j in range(i * i, MAX_PRIME + 1, i):
            is_prime[j] = False

def factorize(x):
    """Return prime factorization of x as dict {prime: exponent}"""
    factors = {}
    temp = x
    for p in primes:
        if p * p > temp:
            break
        while temp % p == 0:
            factors[p] = factors.get(p, 0) + 1
            temp //= p
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    arr = list(map(int, data[1:1+n]))

    # Step 1: Compute total prime exponents across all numbers
    total_factors = {}
    factorizations = []
    for num in arr:
        factors = factorize(num)
        factorizations.append(factors)
        for p, exp in factors.items():
            total_factors[p] = total_factors.get(p, 0) + exp

    # Step 2: Determine maximal possible GCD
    # The GCD's prime exponents are floor(total_exponent / n)
    gcd_factors = {}
    for p, total_exp in total_factors.items():
        share = total_exp // n
        if share > 0:
            gcd_factors[p] = share

    # Compute the actual GCD value
    max_gcd = 1
    for p, exp in gcd_factors.items():
        max_gcd *= p ** exp

    # Step 3: Compute minimal operations
    # For each prime, count how many numbers have less than the share
    operations = 0
    for p, share in gcd_factors.items():
        deficit = 0
        for factors in factorizations:
            current = factors.get(p, 0)
            if current < share:
                deficit += share - current
        operations += deficit

    print(f"{max_gcd} {operations}")

if __name__ == "__main__":
    main()

