    data = sys.stdin.read().strip().split()
    if not data:
        return
    a, b = map(int, data[:2])

    # Binary search for maximum k such that sum_{i=1}^{k} i <= a + b
    lo, hi = 0, 2 * 10**5  # Upper bound: k*(k+1)/2 <= 2e9 => k ~ 2e5
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if mid * (mid + 1) // 2 <= a + b:
            lo = mid
        else:
            hi = mid - 1
    k = lo

    # Greedy assignment: assign largest notes to day with more remaining hours
    day1 = []
    day2 = []
    rem_a, rem_b = a, b

    for note in range(k, 0, -1):
        if rem_a >= rem_b and note <= rem_a:
            day1.append(note)
            rem_a -= note
        elif note <= rem_b:
            day2.append(note)
            rem_b -= note
        elif note <= rem_a:
            day1.append(note)
            rem_a -= note
        else:
            # Should not happen if k is correctly bounded
            pass

    # Output
    print(len(day1))
    if day1:
        print(' '.join(map(str, day1)))
    else:
        print()

    print(len(day2))
    if day2:
        print(' '.join(map(str, day2)))
    else:
        print()

if __name__ == "__main__":
    solve()

