def solve():
    data = input().split()
    n = int(data[0])
    perm = list(map(int, data[1:1+n]))

    # Step 1: Compute original number of swaps (inversions) in O(n^2)
    original_swaps = 0
    for i in range(n):
        for j in range(i+1, n):
            if perm[i] > perm[j]:
                original_swaps += 1

    # Step 2: Precompute prefix counts for efficient range queries
    # prefix[k][x] = number of elements with value < x in positions 0..k-1
    prefix = [[0]*(n+1) for _ in range(n+1)]
    for k in range(1, n+1):
        for x in range(n+1):
            prefix[k][x] = prefix[k-1][x] + (1 if perm[k-1] < x else 0)

    # Step 3: Find minimum swaps after one swap and count ways
    min_swaps = original_swaps
    ways = 0

    for i in range(n):
        for j in range(i+1, n):
            # For positions i < j, swap perm[i] and perm[j]
            a, b = perm[i], perm[j]
            if a == b:
                continue

            # Count elements between i and j with values between a and b
            # We need count of x where min(a,b) < x < max(a,b) and positions in (i, j)
            lo, hi = min(a, b), max(a, b)

            # Count in range (i, j) exclusive
            cnt_between = 0
            for k in range(i+1, j):
                if lo < perm[k] < hi:
                    cnt_between += 1

            # Change in inversions formula
            change = 1 - 2 * cnt_between

            # Adjust for order of a and b
            if a < b:
                change = -change

            new_swaps = original_swaps + change

            if new_swaps < min_swaps:
                min_swaps = new_swaps
                ways = 1
            elif new_swaps == min_swaps:
                ways += 1

    # According to problem guarantee, min_swaps < original_swaps always
    print(f"{min_swaps} {ways}")

if __name__ == "__main__":
    solve()

