import sys

def solve():
    s = sys.stdin.readline().strip()
    n = len(s)
    # Digits that can end a number divisible by 25
    targets = [('0', '0'), ('2', '5'), ('5', '0'), ('7', '5')]
    INF = 10**9
    ans = INF

    for d1, d2 in targets:
        # Find positions from right to left
        pos2 = -1
        for i in range(n-1, -1, -1):
            if s[i] == d2:
                pos2 = i
                break
        if pos2 == -1:
            continue

        pos1 = -1
        for i in range(pos2-1, -1, -1):
            if s[i] == d1:
                pos1 = i
                break
        if pos1 == -1:
            continue

        # Calculate moves to bring these two digits to the end
        # Move pos2 to last position (index n-1)
        moves = (n-1 - pos2)
        # Move pos1 to second last position (index n-2)
        moves += (n-2 - pos1)
        # Adjust if pos1 was to the right of pos2 originally
        if pos1 > pos2:
            moves += 1

        # Check for leading zero after moving these two digits
        # We need at least one non-zero digit among remaining positions
        remaining_positions = set(range(n)) - {pos1, pos2}
        has_non_zero = False
        for i in remaining_positions:
            if s[i] != '0':
                has_non_zero = True
                break

        # Special case: if n == 2, we don't need to check leading zero
        if n == 2:
            has_non_zero = True

        if has_non_zero:
            ans = min(ans, moves)

    print(-1 if ans == INF else ans)

if __name__ == "__main__":
    solve()

