import sys
import math

def cross(o, a, b):
    """Cross product (OA x OB) for points O, A, B."""
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

def convex_hull(points):
    """Andrew's monotone chain algorithm for convex hull."""
    points = sorted(set(points))
    if len(points) <= 1:
        return points

    lower = []
    for p in points:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)

    upper = []
    for p in reversed(points):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)

    return lower[:-1] + upper[:-1]

def collinear(a, b, c):
    """Check if three points are collinear."""
    return cross(a, b, c) == 0

def solve():
    data = list(map(int, sys.stdin.read().strip().split()))
    if not data:
        return
    n = data[0]
    points = [(data[2*i+1], data[2*i+2]) for i in range(n)]

    # Since points are on convex polygon boundary, hull includes all points
    hull = convex_hull(points)
    m = len(hull)

    # Special case: all points collinear (degenerate convex polygon)
    if m <= 2:
        print(1)
        return

    # Check if any three consecutive hull points are collinear
    # This indicates a straight line covering multiple points
    lines_needed = m
    for i in range(m):
        a = hull[i]
        b = hull[(i+1) % m]
        c = hull[(i+2) % m]
        if collinear(a, b, c):
            lines_needed -= 1

    # Minimum lines needed is at least 2 for non-collinear convex polygon
    print(max(2, lines_needed))

if __name__ == "__main__":
    solve()

