import sys

def find_largest_bus_number(m):
    # Dictionary to store count of ways for each sum
    ways_count = {}

    # Upper bound for i: cube root of m
    max_i = int(m ** (1/3)) + 2

    # Generate all sums of cubes i^3 + j^3 where i <= j
    for i in range(1, max_i + 1):
        i_cube = i * i * i
        if i_cube > m:
            break

        for j in range(i, max_i + 1):
            j_cube = j * j * j
            current_sum = i_cube + j_cube

            if current_sum > m:
                break

            # Increment count for this sum
            ways_count[current_sum] = ways_count.get(current_sum, 0) + 1

    # Find the largest number with at least 2 ways
    largest_bus = 0
    for num, count in ways_count.items():
        if count >= 2 and num <= m and num > largest_bus:
            largest_bus = num

    return largest_bus if largest_bus > 0 else "none"

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    m = int(data[0])
    result = find_largest_bus_number(m)
    print(result)

if __name__ == "__main__":
    main()

