def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    idx = 0
    Y = int(data[idx]); idx += 1
    X = int(data[idx]); idx += 1
    x_init = int(data[idx]); idx += 1

    grid = []
    for _ in range(Y):
        row = data[idx]; idx += 1
        grid.append(row)

    # Find castle position
    castle_y = castle_x = -1
    for y in range(Y):
        for x in range(X):
            if grid[y][x] == '@':
                castle_y, castle_x = y, x
                break
        if castle_y != -1:
            break

    # DP table: dp[y][x] = number of ways to reach (y, x)
    dp = [[0] * X for _ in range(Y)]
    dp[Y-1][x_init] = 1  # Starting position

    # Process from bottom to top (since we can only move north)
    for y in range(Y-1, -1, -1):
        for x in range(X-1, -1, -1):
            if dp[y][x] == 0:
                continue
            cell = grid[y][x]
            if cell == '#':
                continue

            # Move north (lower sails)
            if y > 0 and grid[y-1][x] != '#':
                dp[y-1][x] = (dp[y-1][x] + dp[y][x]) % MOD

            # Move east/west based on current
            if cell == '>':
                nx = x + 1
                while nx < X and grid[y][nx] != '#':
                    dp[y][nx] = (dp[y][nx] + dp[y][x]) % MOD
                    if grid[y][nx] == '<' or grid[y][nx] == '>':
                        break
                    nx += 1
            elif cell == '<':
                nx = x - 1
                while nx >= 0 and grid[y][nx] != '#':
                    dp[y][nx] = (dp[y][nx] + dp[y][x]) % MOD
                    if grid[y][nx] == '<' or grid[y][nx] == '>':
                        break
                    nx -= 1
            elif cell == '~':
                # No east/west movement from open sea
                pass

    result = dp[castle_y][castle_x]
    if result == 0:
        print("begin repairs")
    else:
        print(result)

if __name__ == "__main__":
    solve()

