import sys
sys.setrecursionlimit(400000)

input = sys.stdin.readline

def solve():
    N, D = map(int, input().split())
    parent = [0] * N
    for i in range(1, N):
        parent[i] = int(input())

    children = [[] for _ in range(N)]
    for i in range(1, N):
        children[parent[i]].append(i)

    # dp[node][state]:
    # state = 0: node is marked
    # state = d (1 <= d <= D): node is not marked, nearest marked descendant is at distance d
    # state = D+1: node is not marked, no marked descendant in subtree
    INF = -10**9
    dp = [[INF] * (D+2) for _ in range(N)]

    def dfs(u):
        # Initialize with base cases
        # If mark this node
        dp[u][0] = 1  # count this node
        # If don't mark, no marked descendants yet
        dp[u][D+1] = 0

        for v in children[u]:
            dfs(v)

            # Merge child v's DP into u's DP
            new_dp = [INF] * (D+2)

            # Try all combinations of u's state and v's state
            for su in range(D+2):
                if dp[u][su] < 0:
                    continue
                for sv in range(D+2):
                    if dp[v][sv] < 0:
                        continue

                    # Case 1: u is marked (su = 0)
                    if su == 0:
                        # v cannot be marked (distance would be 1 < D)
                        if sv == 0:
                            continue
                        # v can have marked descendants at distance >= D from u
                        if sv <= D:
                            # Distance from u to v's nearest marked = sv + 1
                            if sv + 1 >= D:
                                new_dp[0] = max(new_dp[0], dp[u][0] + dp[v][sv])
                        else:  # sv == D+1 (no marked in v's subtree)
                            new_dp[0] = max(new_dp[0], dp[u][0] + dp[v][D+1])

                    # Case 2: u is not marked, has nearest marked at distance su (1 <= su <= D)
                    elif 1 <= su <= D:
                        # v cannot be marked (distance would be su + 1)
                        if sv == 0:
                            if su + 1 >= D:
                                new_dp[su] = max(new_dp[su], dp[u][su] + dp[v][0])
                        else:
                            # v has nearest marked at distance sv
                            if sv <= D:
                                # Distance between u's nearest and v's nearest = su + sv + 1
                                if su + sv + 1 >= D:
                                    new_min = min(su, sv + 1)
                                    new_dp[new_min] = max(new_dp[new_min], dp[u][su] + dp[v][sv])
                            else:  # sv == D+1
                                new_dp[su] = max(new_dp[su], dp[u][su] + dp[v][D+1])

                    # Case 3: u has no marked descendants (su == D+1)
                    else:  # su == D+1
                        if sv == 0:
                            # v is marked, so u's nearest becomes distance 1
                            new_dp[1] = max(new_dp[1], dp[u][D+1] + dp[v][0])
                        elif 1 <= sv <= D:
                            # v has nearest marked at distance sv
                            new_dp[sv + 1] = max(new_dp[sv + 1], dp[u][D+1] + dp[v][sv])
                        else:  # sv == D+1
                            new_dp[D+1] = max(new_dp[D+1], dp[u][D+1] + dp[v][D+1])

            # Update dp[u] with merged results
            for i in range(D+2):
                dp[u][i] = new_dp[i]

        # After processing all children, we can also consider marking u
        # if it wasn't marked before and distance constraints allow
        for d in range(1, D+2):
            if dp[u][d] >= 0:
                # Check if we can mark u
                # Need distance from nearest marked descendant to be >= D
                if d >= D:
                    dp[u][0] = max(dp[u][0], dp[u][d] + 1)

    dfs(0)

    # Answer is max over all states at root
    ans = 0
    for i in range(D+2):
        ans = max(ans, dp[0][i])
    print(ans)

if __name__ == "__main__":
    solve()

