import sys

def rotate_row(matrix, i, k):
    """Rotate i-th row (0-indexed) k elements to the right"""
    row = matrix[i]
    k = k % len(row)
    if k:
        matrix[i] = row[-k:] + row[:-k]

def rotate_col(matrix, j, k):
    """Rotate j-th column (0-indexed) k elements down"""
    col = [matrix[i][j] for i in range(len(matrix))]
    k = k % len(col)
    if k:
        rotated = col[-k:] + col[:-k]
        for i in range(len(matrix)):
            matrix[i][j] = rotated[i]

def negate_row(matrix, i, row_negated):
    """Negate i-th row if not already negated"""
    if not row_negated[i]:
        for j in range(len(matrix[0])):
            matrix[i][j] *= -1
        row_negated[i] = True

def negate_col(matrix, j, col_negated):
    """Negate j-th column if not already negated"""
    if not col_negated[j]:
        for i in range(len(matrix)):
            matrix[i][j] *= -1
        col_negated[j] = True

def matrix_sum(matrix):
    """Calculate sum of all elements in matrix"""
    return sum(sum(row) for row in matrix)

