    col_negated = [False] * C
    operations = []

    # Strategy: Make all elements non-negative if possible
    # First, handle rows: if a row has more negative than positive sum, negate it
    for i in range(R):
        row_sum = sum(matrix[i])
        if row_sum < 0:
            negate_row(matrix, i, row_negated)
            operations.append(f"negR {i+1}")

    # Then handle columns similarly
    for j in range(C):
        col_sum = sum(matrix[i][j] for i in range(R))
        if col_sum < 0:
            negate_col(matrix, j, col_negated)
            operations.append(f"negS {j+1}")

    # After making all rows/columns have non-negative sum,
    # we can use rotations to potentially increase sum further
    # For each row, find rotation that maximizes its sum
    for i in range(R):
        best_sum = sum(matrix[i])
        best_k = 0
        row = matrix[i]
        for k in range(1, C):
            rotated = row[-k:] + row[:-k]
