import sys

def solve():
    data = sys.stdin.read().strip().split('\n')
    if not data:
        return

    I = data[0].strip()
    O = data[1].strip() if len(data) > 1 else ''

    # Check if lengths match when considering possible encodings
    # We need to find possible encodings for '+' and '-' such that
    # when we replace '+' and '-' in I with their encodings, we get O

    # First, let's find all positions of '+' and '-' in I
    plus_positions = [i for i, ch in enumerate(I) if ch == '+']
    minus_positions = [i for i, ch in enumerate(I) if ch == '-']

    # If there are no '+' or '-' in I, then O must equal I
    if not plus_positions and not minus_positions:
        if I == O:
            print('<any> <empty>')
        else:
            print('corrupted')
        return

    # We'll try to find possible encodings by matching I to O
    # The idea: iterate through O while matching characters from I
    # When we encounter '+' or '-' in I, we need to consume some substring from O
    # as its encoding

    def find_encodings():
        results = []

        # Try all possible ways to match I to O
        # We'll use recursion/backtracking

        # First, let's create a list of tokens from I
        tokens = []
        i = 0
        while i < len(I):
            if I[i] == '+' or I[i] == '-':
                tokens.append(I[i])
                i += 1
            else:
                # Regular character
                start = i
                while i < len(I) and I[i] not in '+-':
                    i += 1
                tokens.append(I[start:i])

        # Now we need to match tokens to O
        # We'll use memoization to avoid repeated work
        from functools import lru_cache

        @lru_cache(None)
        def dfs(token_idx, o_idx):
            """Return list of (plus_enc, minus_enc) pairs that work from this state"""
            if token_idx == len(tokens) and o_idx == len(O):
                return [('', '')]  # Empty encodings work
            if token_idx == len(tokens) or o_idx > len(O):
                return []

            token = tokens[token_idx]

            if token not in '+-':
                # Regular string token
                if o_idx + len(token) > len(O):
                    return []
                if O[o_idx:o_idx + len(token)] == token:
                    return dfs(token_idx + 1, o_idx + len(token))
                else:
                    return []
            else:
                # '+' or '-' token
                results = []
                # Try all possible substrings as encoding
                for end in range(o_idx, len(O) + 1):
                    encoding = O[o_idx:end]
                    # Continue with this encoding
                    next_results = dfs(token_idx + 1, end)
                    for plus_enc, minus_enc in next_results:
                        if token == '+':
                            results.append((encoding, minus_enc))
                        else:
                            results.append((plus_enc, encoding))
                return results

        raw_results = dfs(0, 0)

        if not raw_results:
            return []

        # Deduplicate and format results
        seen = set()
        for plus_enc, minus_enc in raw_results:
            # Format according to problem requirements
            plus_str = '<empty>' if plus_enc == '' else ('<any>' if plus_enc == '*' else plus_enc)
            minus_str = '<empty>' if minus_enc == '' else ('<any>' if minus_enc == '*' else minus_enc)

            # But wait, we need to determine if encoding can be anything
            # Actually, from our search, we get specific encodings
            # We need to check if multiple encodings are possible

            # For now, just collect unique pairs
            seen.add((plus_str, minus_str))

        # Convert to list
        return list(seen)

    encodings = find_encodings()

    if not encodings:
        print('corrupted')
    else:
        # We need to output all possible encodings
        # But the problem says: "Each line must have two strings a^+_i and a^-_i"
        # So we output each pair on separate line
        for plus_enc, minus_enc in encodings:
            print(f"{plus_enc} {minus_enc}")

if __name__ == "__main__":
    solve()

