import sys

def solve():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    I = data[0].strip()
    O = data[1].strip() if len(data) > 1 else ""

    # Special case: empty strings
    if I == "" and O == "":
        print("<any> <any>")
        return
    if I == "":
        print("corrupted")
        return
    if O == "":
        # O empty, I non-empty: only possible if all + and - encode to empty
        for ch in I:
            if ch in "+-":
                print("<empty> <empty>")
                return
        print("corrupted")
        return

    n = len(I)
    m = len(O)

    # Determine possible encodings for + and -
    # We'll try to match I to O with + and - replaced by substrings
    # Let enc[0] be for '+', enc[1] for '-'
    candidates = []

    # Try all possible lengths for + encoding (0 to m)
    for len_plus in range(m + 1):
        for len_minus in range(m + 1):
            # Quick check: total length must match
            total_len = 0
            for ch in I:
                if ch == '+':
                    total_len += len_plus
                elif ch == '-':
                    total_len += len_minus
                else:
                    total_len += 1
            if total_len != m:
                continue

            # Now verify the actual match
            i_idx = 0
            o_idx = 0
            enc_plus = None
            enc_minus = None
            valid = True

            while i_idx < n and o_idx < m:
                ch = I[i_idx]
                if ch == '+':
                    if enc_plus is None:
                        enc_plus = O[o_idx:o_idx + len_plus]
                    else:
                        if O[o_idx:o_idx + len_plus] != enc_plus:
                            valid = False
                            break
                    o_idx += len_plus
                elif ch == '-':
                    if enc_minus is None:
                        enc_minus = O[o_idx:o_idx + len_minus]
                    else:
                        if O[o_idx:o_idx + len_minus] != enc_minus:
                            valid = False
                            break
