input = sys.stdin.read
data = input().splitlines()
n, m = map(int, data[0].split())
grid = [list(row) for row in data[1:1+n]]

# Find bounding box of all white pixels
min_row, max_row = n, -1
min_col, max_col = m, -1
white_positions = []

for i in range(n):
    for j in range(m):
        if grid[i][j] == 'w':
            white_positions.append((i, j))
            min_row = min(min_row, i)
            max_row = max(max_row, i)
            min_col = min(min_col, j)
            max_col = max(max_col, j)

# Calculate required square size
height = max_row - min_row + 1
width = max_col - min_col + 1
size = max(height, width)

if size > n or size > m:
    print(-1)
    sys.exit(0)

# Try all possible top-left corners for the square
found = False
result_grid = None

for top in range(n - size + 1):
    for left in range(m - size + 1):
        bottom = top + size - 1
        right = left + size - 1

        # Check if all white pixels are on the border of this square
        valid = True
        for r, c in white_positions:
            if not (r == top or r == bottom or c == left or c == right):
                valid = False
                break
            if not (top <= r <= bottom and left <= c <= right):
                valid = False
                break

        if not valid:
            continue

        # Create candidate grid
        candidate = [row[:] for row in grid]

        # Mark the border
        for r in range(top, bottom + 1):
            for c in range(left, right + 1):
                if r == top or r == bottom or c == left or c == right:
                    if candidate[r][c] == '.':
                        candidate[r][c] = '+'

        # Verify no extra white pixels were created
        # (all '+' should be on border and all 'w' should remain)
        verification_ok = True
        for r in range(n):
            for c in range(m):
                if candidate[r][c] == 'w':
                    if not (r == top or r == bottom or c == left or c == right):
                        verification_ok = False
                        break
                    if not (top <= r <= bottom and left <= c <= right):
                        verification_ok = False
                        break
                elif candidate[r][c] == '+':
                    if not (r == top or r == bottom or c == left or c == right):
                        verification_ok = False
                        break
                    if not (top <= r <= bottom and left <= c <= right):
                        verification_ok = False
                        break
            if not verification_ok:
                break

        if verification_ok:
            found = True
            result_grid = candidate
            break

    if found:
        break

if not found:
    print(-1)
else:
    for row in result_grid:
        print(''.join(row))

