import sys
import math

# Function to check if a number is prime (p >= 3)
def is_prime(num):
    if num < 2:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    limit = int(math.isqrt(num)) + 1
    for i in range(3, limit, 2):
        if num % i == 0:
            return False
    return True

# Function to find the smallest prime >= 3 that fits within remaining cards
def find_prime_for_flip(start_idx, max_card):
    # We need to flip p consecutive cards starting from start_idx
    # So p must satisfy: start_idx + p - 1 <= max_card
    # We want the smallest prime p >= 3 that satisfies this
    max_possible = max_card - start_idx + 1
    if max_possible < 3:
        return -1  # Cannot flip any valid prime length
    for p in range(3, max_possible + 1):
        if is_prime(p):
            return p
    return -1  # No prime found (shouldn't happen for large enough max_possible)

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    N = int(data[0])
    cards = list(map(int, data[1:1+N]))

    # We only care about cards up to the maximum face-up card
    max_card = cards[-1]

    # Create a boolean array to track face-up states
    # Index 1-based for simplicity
    state = [False] * (max_card + 2)  # Extra padding for safety
    for x in cards:
        state[x] = True  # True means face-up

    operations = 0

    # Process cards from left to right
    for i in range(1, max_card + 1):
        if state[i]:  # Found a face-up card
            # Find the smallest prime p >= 3 that we can use to flip starting from i
            p = find_prime_for_flip(i, max_card)
            if p == -1:
                # This shouldn't happen if we process correctly
                # But if it does, we can't flip this card
                continue

            # Flip p consecutive cards starting from i
            for j in range(i, i + p):
                state[j] = not state[j]
            operations += 1

    # Verify all cards are face-down
    for i in range(1, max_card + 1):
        if state[i]:
            # If any card is still face-up, the approach failed
            # This shouldn't happen with the given constraints
            return -1

    print(operations)

if __name__ == "__main__":
    solve()

