import sys
sys.setrecursionlimit(1000000)

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    r, c = map(int, data[:2])
    grid = data[2:]

    # Directions: up, down, left, right
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Mark all water cells as visited
    visited = [[False] * c for _ in range(r)]
    for i in range(r):
        for j in range(c):
            if grid[i][j] == 'W':
                visited[i][j] = True

    def dfs(i, j):
        stack = [(i, j)]
        visited[i][j] = True
        while stack:
            x, y = stack.pop()
            for dx, dy in dirs:
                nx, ny = x + dx, y + dy
                if 0 <= nx < r and 0 <= ny < c and not visited[nx][ny]:
                    visited[nx][ny] = True
                    stack.append((nx, ny))

    islands = 0
    # Count islands from land cells
    for i in range(r):
        for j in range(c):
            if grid[i][j] == 'L' and not visited[i][j]:
                islands += 1
                dfs(i, j)

    # For clouds, we can treat them as water to minimize islands
    # Since clouds can be either land or water, to minimize islands,
    # we interpret all clouds as water (which doesn't form islands)
    # The islands counted above are only from definite land cells
    print(islands)

if __name__ == "__main__":
    solve()

