from collections import deque

def solve():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    n = int(data[0])
    words = data[1:1+n]
    start, end = words[0], words[1]
    dictionary = set(words)
    word_len = len(start)

    # BFS from start to end without any added word
    def bfs(start, end, dict_set):
        if start == end:
            return 0
        visited = {start}
        q = deque([(start, 0)])
        while q:
            word, dist = q.popleft()
            for i in range(word_len):
                for c in 'ABCDEFGHIJKLMNOPQRSTUVWXYZ':
                    if c == word[i]:
                        continue
                    new_word = word[:i] + c + word[i+1:]
                    if new_word == end:
                        return dist + 1
                    if new_word in dict_set and new_word not in visited:
                        visited.add(new_word)
                        q.append((new_word, dist + 1))
        return -1

    original_dist = bfs(start, end, dictionary)
    if original_dist == -1:
        # No path exists even without adding any word
        print("0")
        print("-1")
        return

    # Try adding each possible word
    best_word = "0"
    best_dist = original_dist

    # Generate all possible words of same length
    for i in range(word_len):
        for c in 'ABCDEFGHIJKLMNOPQRSTUVWXYZ':
            # Try adding a word that differs from start or end by one letter
            for base in [start, end]:
                candidate = base[:i] + c + base[i+1:]
                if candidate in dictionary:
                    continue
                new_dict = dictionary | {candidate}
                dist = bfs(start, end, new_dict)
                if dist != -1 and dist < best_dist:
                    best_dist = dist
                    best_word = candidate
                elif dist != -1 and dist == best_dist and candidate < best_word:
                    best_word = candidate

    # Also try words that are one letter different from any dictionary word
    for word in dictionary:
        for i in range(word_len):
            for c in 'ABCDEFGHIJKLMNOPQRSTUVWXYZ':
                if c == word[i]:
                    continue
                candidate = word[:i] + c + word[i+1:]
                if candidate in dictionary:
                    continue
                new_dict = dictionary | {candidate}
                dist = bfs(start, end, new_dict)
                if dist != -1 and dist < best_dist:
                    best_dist = dist
                    best_word = candidate
                elif dist != -1 and dist == best_dist and candidate < best_word:
                    best_word = candidate

    print(best_word)
    print(best_dist)

