    return 31

def date_to_day(day, month):
    """Convert date to day number in year (1-365)."""
    # Months are 1-indexed
    return (month - 1) * 31 + day

def parse_input():
    data = sys.stdin.read().strip().split()
    if not data:
        return None
    it = iter(data)
    N = int(next(it))
    M = int(next(it))
    observations = []
    for _ in range(N):
        d1 = int(next(it))
        m1 = int(next(it))
        d2 = int(next(it))
        m2 = int(next(it))
        start = date_to_day(d1, m1)
        end = date_to_day(d2, m2)
        # Handle wrap-around across year boundary
        if end < start:
            end += 365
        duration = end - start + 1  # inclusive
        counts = [int(next(it)) for _ in range(M)]
        observations.append((duration, counts))
    return N, M, observations

def solve():
    parsed = parse_input()
    if parsed is None:
        return "-1"
