    # Compute upper bounds for each event type
    upper_bounds = [365] * M
    for j in range(M):
        min_val = 365
        for dur, counts in observations:
            if counts[j] > 0:
                val = dur // counts[j]
                if val < min_val:
                    min_val = val
        if min_val < 365:
            upper_bounds[j] = min_val

    # Order events by restrictiveness (smallest upper bound first)
    order = sorted(range(M), key=lambda i: upper_bounds[i])
    rev_order = [0] * M
    for idx, ev in enumerate(order):
        rev_order[ev] = idx

    # Reorder counts in observations to match order
    reordered_obs = []
    for dur, counts in observations:
        reordered_counts = [counts[ev] for ev in order]
        reordered_obs.append((dur, reordered_counts))

    # DFS with pruning
    solution = [0] * M

    def dfs(pos, current_sums):
        if pos == M:
            # Check all observations match exactly
            for dur, counts in reordered_obs:
                total = sum(counts[i] * solution[i] for i in range(M))
                if total != dur:
                    return False
            return True

        # Try possible durations for event at position pos
        for d in range(1, upper_bounds[order[pos]] + 1):
            # Prune: check if adding this duration would exceed any observation
            valid = True
            new_sums = current_sums[:]
            for i in range(N):
                dur, counts = reordered_obs[i]
                new_sums[i] += counts[pos] * d
                if new_sums[i] > dur:
                    valid = False
                    break
            if not valid:
