import sys

input = sys.stdin.read
def solve():
    data = input().split()
    idx = 0
    n = int(data[idx]); idx += 1
    k = int(data[idx]); idx += 1
    a = [int(data[idx + i]) for i in range(n)]; idx += n
    q = int(data[idx]); idx += 1
    queries = [int(data[idx + i]) for i in range(q)]; idx += q

    max_query = max(queries)
    INF = 10**9
    # dp[s] = minimal bills to achieve sum s using any single denomination
    dp = [INF] * (max_query + 1)
    dp[0] = 0
    for denom in a:
        for s in range(denom, max_query + 1):
            if dp[s - denom] + 1 <= k:
                dp[s] = min(dp[s], dp[s - denom] + 1)

    # Precompute reachable sums with their bill counts
    reachable = []
    for s in range(max_query + 1):
        if dp[s] <= k:
            reachable.append((s, dp[s]))

    results = []
    for x in queries:
        best = INF
        # Try all possible sums from first denomination
        for s1, cnt1 in reachable:
            if s1 > x:
                break
            s2 = x - s1
            if s2 < 0:
                continue
            # Check if s2 is reachable with minimal bills
            cnt2 = dp[s2]
            if cnt2 <= k:
                total = cnt1 + cnt2
                if total <= k:
                    best = min(best, total)
        if best == INF:
            results.append(-1)
        else:
            results.append(best)

    print('\n'.join(map(str, results)))

if __name__ == "__main__":
    solve()

