import sys
sys.setrecursionlimit(10**6)

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    adj = [[] for _ in range(n)]
    rev_adj = [[] for _ in range(n)]

    for _ in range(m):
        a = int(next(it)) - 1
        b = int(next(it)) - 1
        adj[a].append(b)
        rev_adj[b].append(a)

    # Kosaraju's algorithm for SCC
    visited = [False] * n
    order = []

    def dfs1(u):
        visited[u] = True
        for v in adj[u]:
            if not visited[v]:
                dfs1(v)
        order.append(u)

    for i in range(n):
        if not visited[i]:
            dfs1(i)

    comp = [-1] * n
    comp_count = 0

    def dfs2(u, c):
        comp[u] = c
        for v in rev_adj[u]:
            if comp[v] == -1:
                dfs2(v, c)

    for u in reversed(order):
        if comp[u] == -1:
            dfs2(u, comp_count)
            comp_count += 1

    # If already strongly connected
    if comp_count == 1:
        print(0)
        return

    # Build condensation DAG
    in_deg = [0] * comp_count
    out_deg = [0] * comp_count

    for u in range(n):
        for v in adj[u]:
            if comp[u] != comp[v]:
                out_deg[comp[u]] += 1
                in_deg[comp[v]] += 1

    sources = sum(1 for i in range(comp_count) if in_deg[i] == 0)
    sinks = sum(1 for i in range(comp_count) if out_deg[i] == 0)

    # Minimum edges to make strongly connected
    result = max(sources, sinks)
    print(result)

if __name__ == "__main__":
    solve()

