import sys

def can_make_equal(arr):
    """
    Check if all numbers can be made equal by repeatedly multiplying by 2 and 3.

    The key insight is that we can only change numbers by multiplying by 2 and 3,
    which means we can only change the prime factorization by adding factors of 2 and 3.

    Therefore, all numbers must have the same "core" value after removing all factors of 2 and 3.
    """
    # Find the core value for the first element
    def get_core(x):
        while x % 2 == 0:
            x //= 2
        while x % 3 == 0:
            x //= 3
        return x

    first_core = get_core(arr[0])

    # Check if all elements have the same core
    for num in arr[1:]:
        if get_core(num) != first_core:
            return False
    return True


