    for a in range(10):
        if len(positions[a]) < min_threshold:
            continue
        for b in range(10):
            if len(positions[b]) < min_threshold:
                continue
            for c in range(10):
                if len(positions[c]) < min_threshold:
                    continue

                # For each occurrence of a, find b at distance n
                for i in positions[a]:
                    for j in positions[b]:
                        n = j - i
                        if n <= 0:
                            continue
                        # Check if there's c at distance m after b
                        for k in positions[c]:
                            m = k - j
                            if m <= 0:
                                continue

                            # Quick check: n+m must be within bounds
