import sys

def read_input():
    data = sys.stdin.read().strip().split()
    if not data:
        return 0, []
    p = int(data[0])
    seq = list(map(int, data[1:1 + p]))
    return p, seq

def find_triple_correlation(p, seq):
    min_threshold = (p + 39) // 40 + 1  # ceil(p/40) + 1
    best = None  # (a, n, b, m, c, first_occurrence)

    # Try all possible a, b, c from 0 to 9
    for a in range(10):
        for b in range(10):
            for c in range(10):
                # Try all possible n, m where positions are valid
                for n in range(1, p - 1):  # n >= 1, need space for b and c
                    for m in range(1, p - n):  # m >= 1, need space for c after b
                        count = 0
                        first_occurrence = None
                        valid = True

                        # Check all starting positions i for pattern a...b...c
                        for i in range(p - (n + m)):
                            if seq[i] == a and seq[i + n] == b and seq[i + n + m] == c:
                                count += 1
                                if first_occurrence is None:
                                    first_occurrence = i

                        # Check the three conditions from problem statement
                        # Condition 1: a followed n later by b implies c m after b
                        for i in range(p - n):
                            if seq[i] == a and seq[i + n] == b:
                                # Check if b is within m-1 of end
                                if i + n + m < p:
                                    if seq[i + n + m] != c:
                                        valid = False
                                        break
                        if not valid:
                            continue

                        # Condition 2: b followed m later by c implies a n before b
                        for i in range(p - m):
                            if seq[i] == b and seq[i + m] == c:
                                # Check if b is within n-1 of beginning
                                if i - n >= 0:
                                    if seq[i - n] != a:
                                        valid = False
                                        break
                        if not valid:
                            continue

                        # Condition 3: a followed n+m later by c implies b n after a
                        for i in range(p - (n + m)):
                            if seq[i] == a and seq[i + n + m] == c:
                                if seq[i + n] != b:
                                    valid = False
                                    break
                        if not valid:
                            continue

                        # Check minimum occurrence threshold
                        if count >= min_threshold:
                            # Update best according to tie-breaking rules
                            if best is None:
                                best = (a, n, b, m, c, first_occurrence)
                            else:
                                # Compare first occurrence
                                if first_occurrence < best[5]:
                                    best = (a, n, b, m, c, first_occurrence)
                                elif first_occurrence == best[5]:
                                    # Compare n
                                    if n < best[1]:
                                        best = (a, n, b, m, c, first_occurrence)
                                    elif n == best[1]:
                                        # Compare m
                                        if m < best[3]:
                                            best = (a, n, b, m, c, first_occurrence)

    return best

def main():
    p, seq = read_input()
    if p == 0:
        print("random sequence")
        return

    result = find_triple_correlation(p, seq)

    if result is None:
        print("random sequence")
    else:
        a, n, b, m, c, _ = result
        print(f"triple correlation {a}({n}){b}({m}){c} found")

if __name__ == "__main__":
    main()

