    # Helper function to find maximum length substring of target char
    def max_length_for_char(target_char):
        left = 0
        changes_used = 0
        max_len = 0

        for right in range(n):
            if s[right] != target_char:
                changes_used += 1

            # Shrink window if we've used too many changes
            while changes_used > k:
                if s[left] != target_char:
                    changes_used -= 1
                left += 1

            # Update maximum length
            max_len = max(max_len, right - left + 1)

