import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    L1 = int(data[0])
    L2 = int(data[1])
    N = int(data[2])
    tubes = list(map(int, data[3:3+N]))

    # Step 1: Generate all possible pairs of tubes (i < j) and store (sum, indices)
    pairs = []
    for i in range(N):
        for j in range(i+1, N):
            s = tubes[i] + tubes[j]
            pairs.append((s, i, j))

    # Step 2: Sort pairs by sum descending
    pairs.sort(key=lambda x: x[0], reverse=True)

    # Step 3: For each pair, try to find another pair with disjoint indices
    # that fits in the other distance constraint
    best_total = -1

    # We'll iterate through pairs and for each, try to find the best complementary pair
    # Since pairs are sorted by sum descending, we can break early if no better solution possible
    for idx, (sum1, i1, j1) in enumerate(pairs):
        if sum1 > L1:
            continue
        # Remaining capacity for L2
        remaining_L2 = L2

        # Find best pair with disjoint indices that fits in L2
        best_sum2 = -1
        for sum2, i2, j2 in pairs:
            if sum2 > remaining_L2:
                continue
            # Check if indices are disjoint
            if i2 != i1 and i2 != j1 and j2 != i1 and j2 != j1:
                best_sum2 = max(best_sum2, sum2)
                # Since pairs are sorted descending, first valid is best for current sum1
                # But we need to continue to check all for maximum total
                # We can break if we found a pair that uses the full L2 capacity
                if sum2 == remaining_L2:
                    break

        if best_sum2 != -1:
            best_total = max(best_total, sum1 + best_sum2)

        # Early break: if even with maximum possible sum2 we can't beat current best
        # Since pairs are sorted descending, remaining pairs will have smaller sum1
        max_possible = sum1 + L2
        if max_possible <= best_total:
            break

    # Also check the symmetric case: first pair for L2, second for L1
    for idx, (sum2, i1, j1) in enumerate(pairs):
        if sum2 > L2:
            continue
        remaining_L1 = L1

        best_sum1 = -1
        for sum1, i2, j2 in pairs:
            if sum1 > remaining_L1:
                continue
            if i2 != i1 and i2 != j1 and j2 != i1 and j2 != j1:
                best_sum1 = max(best_sum1, sum1)
                if sum1 == remaining_L1:
                    break

        if best_sum1 != -1:
            best_total = max(best_total, sum2 + best_sum1)

        max_possible = sum2 + L1
        if max_possible <= best_total:
            break

    if best_total == -1:
        print("Impossible")
    else:
        print(best_total)

