                right_count += 1
            else:
                break

        # Minimum deletions needed is the smaller of left_count and right_count
        # because we need to remove all characters that prevent reduction
        result = min(left_count, right_count)
        results.append(str(result))

    sys.stdout.write('\n'.join(results))

