import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    grid = []
    idx = 1
    for _ in range(n):
        row = data[idx]
        idx += 1
        grid.append(row)

    # Check if any row is completely evil
    row_evil = [False] * n
    col_evil = [False] * n
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 'E':
                row_evil[i] = True
                col_evil[j] = True

    # If there exists a row and a column that are completely evil, impossible
    if all(row_evil) and all(col_evil):
        print(-1)
        return

    # Strategy: Try to cover all rows or all columns
    # Option 1: Cover all rows with spells on non-evil cells
    row_solution = []
    possible_row = True
    for i in range(n):
        found = False
        for j in range(n):
            if grid[i][j] == '.':
                row_solution.append((i+1, j+1))
                found = True
                break
        if not found:
            possible_row = False
            break

    # Option 2: Cover all columns with spells on non-evil cells
    col_solution = []
    possible_col = True
    for j in range(n):
        found = False
        for i in range(n):
            if grid[i][j] == '.':
                col_solution.append((i+1, j+1))
                found = True
                break
        if not found:
            possible_col = False
            break

    if not possible_row and not possible_col:
        print(-1)
    elif possible_row and possible_col:
        # Choose the one with fewer spells (both have n spells)
        # Actually both have n spells, so either is fine
        for r, c in row_solution:
            print(r, c)
    elif possible_row:
        for r, c in row_solution:
            print(r, c)
    else:
        for r, c in col_solution:
            print(r, c)

if __name__ == "__main__":
    solve()

