# Precompute all valid rows (bitmask representation)
def get_valid_rows(n):
    masks = []
    for mask in range(1 << n):
        valid = True
        for i in range(n):
            if not (mask >> i) & 1:
                continue
            # Check knight attacks within same row (2x3 rectangle horizontally)
            if i + 2 < n and (mask >> (i + 2)) & 1:
                valid = False
                break
            # Check knight attacks within same row (2x3 rectangle vertically)
            # Actually, knights attack in L-shape: (dx, dy) = (±1, ±2) or (±2, ±1)
            # For same row, need to check columns difference 2 and rows difference 1
            # But within same row, knights cannot attack each other
            # The attack pattern requires different rows
        if valid:
            masks.append(mask)
