import sys

MOD = 10**9 + 9

def get_valid_rows(n):
    """Generate all valid rows of length n where no knights attack horizontally."""
    valid = []
    for mask in range(1 << n):
        ok = True
        # Check for knights attacking horizontally: positions i and i+2
        for i in range(n - 2):
            if (mask >> i) & 1 and (mask >> (i + 2)) & 1:
                ok = False
                break
        if ok:
            valid.append(mask)
    return valid

def compatible(row1, row2, n):
    """Check if two rows can be placed adjacent without knights attacking."""
    for i in range(n):
        if (row1 >> i) & 1:
            # Check vertical attacks: positions (i-1, i+1) in adjacent row
            for di in [-1, 1]:
                j = i + di
                if 0 <= j < n and (row2 >> j) & 1:
                    return False
    return True

def mat_mul(A, B, size):
    """Multiply two matrices modulo MOD."""
    C = [[0] * size for _ in range(size)]
    for i in range(size):
        for k in range(size):
            if A[i][k]:
                for j in range(size):
                    C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
    return C

def mat_pow(M, power, size):
    """Fast exponentiation of matrix M^power."""
    result = [[int(i == j) for j in range(size)] for i in range(size)]
    while power > 0:
        if power & 1:
            result = mat_mul(result, M, size)
        M = mat_mul(M, M, size)
        power >>= 1
    return result

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n, m = map(int, data)

    valid_rows = get_valid_rows(n)
    k = len(valid_rows)

    # Build transition matrix
    trans = [[0] * k for _ in range(k)]
    for i, r1 in enumerate(valid_rows):
        for j, r2 in enumerate(valid_rows):
            if compatible(r1, r2, n):
                trans[i][j] = 1

    # Initial vector: one way for each valid row in first column
    init = [1] * k

    if m == 1:
        # Only one column: sum of all valid rows
        ans = sum(init) % MOD
        print(ans)
        return

    # Compute transitions for m-1 steps
    trans_pow = mat_pow(trans, m - 1, k)

    # Multiply initial vector by transition matrix^(m-1)
    final = [0] * k
    for i in range(k):
        for j in range(k):
            final[j] = (final[j] + init[i] * trans_pow[i][j]) % MOD

    ans = sum(final) % MOD
    print(ans)

if __name__ == "__main__":
    solve()

