import sys
import re

def is_vowel(c):
    """Return True if c is a vowel according to the problem rules."""
    return c in 'AEIOUY'

def count_syllables(word):
    """Count syllables in a word according to the problem rules."""
    # Extract alphabetic part
    alphabetic = ''.join(ch for ch in word if ch.isalpha())
    if not alphabetic:
        return 1  # Non-alphabetic word still has 1 syllable

    alphabetic = alphabetic.upper()
    n = len(alphabetic)

    # Apply silent E rule
    if n >= 1 and alphabetic[-1] == 'E':
        if n >= 3 and alphabetic[-2] == 'L' and not is_vowel(alphabetic[-3]):
            # Keep the E (as in 'able')
            pass
        else:
            # Silent E, remove it
            alphabetic = alphabetic[:-1]
            n = len(alphabetic)

    # Apply ES rule
    if n >= 2 and alphabetic[-2:] == 'ES':
        if n >= 3 and not is_vowel(alphabetic[-3]) and (n < 4 or not is_vowel(alphabetic[-4])):
            # Keep ES (as in 'witches')
            pass
        else:
            # Remove ES
            alphabetic = alphabetic[:-2]
            n = len(alphabetic)

    if n == 0:
        return 1

    # Mark vowels, handling Y and QU exceptions
    is_v = [False] * n
    i = 0
    while i < n:
        c = alphabetic[i]
        if c == 'Q' and i+1 < n and alphabetic[i+1] == 'U':
            # QU is consonant
            i += 2
            continue
        if c == 'Y':
            # Y is consonant if followed by another vowel
            if i+1 < n and is_vowel(alphabetic[i+1]) and alphabetic[i+1] != 'Y':
                i += 1
                continue
        if is_vowel(c):
            is_v[i] = True
        i += 1

    # Count syllable divisions
    syllables = 0
    i = 0
    while i < n:
        # Find next vowel
        while i < n and not is_v[i]:
            i += 1
        if i >= n:
            break
        # Start of a vowel group
        start = i
        while i < n and is_v[i]:
            i += 1
        # End of vowel group
        end = i - 1
        # Find next consonant group after this vowel group
        while i < n and not is_v[i]:
            i += 1
        # If there's another vowel after consonants, this forms a syllable division
        if i < n:
            syllables += 1
        else:
            # Last vowel group
            syllables += 1

    return max(1, syllables)

def split_haiku(words, syllables):
    """Try to split words into haiku (5,7,5 syllables)."""
    n = len(words)
    # DP: dp[i][j] = can we split first i words into j lines with given syllables?
    # We'll track the splits

    # Try all possible splits for 3 lines
    for i in range(1, n):
        for j in range(i+1, n):
            s1 = sum(syllables[:i])
            s2 = sum(syllables[i:j])
            s3 = sum(syllables[j:])
            if s1 == 5 and s2 == 7 and s3 == 5:
                return (
                    ' '.join(words[:i]),
                    ' '.join(words[i:j]),
                    ' '.join(words[j:])
                )
    return None

def main():
    line = sys.stdin.readline().rstrip('\n')
    if not line:
        return

    # Split into words preserving original form
    words = []
    pos = 0
    while pos < len(line):
        # Skip spaces
        while pos < len(line) and line[pos] == ' ':
            pos += 1
        if pos >= len(line):
            break
        # Find word end
        end = pos
        # Find alphabetic part
        while end < len(line) and line[end].isalpha():
            end += 1
        # Find non-alphabetic suffix
        while end < len(line) and line[end] != ' ' and not line[end].isalpha():
            end += 1
        word = line[pos:end]
        words.append(word)
        pos = end

    # Count syllables for each word
    syllables = [count_syllables(word) for word in words]
    total = sum(syllables)

    if total != 19:  # 5+7+5
        # Cannot form haiku
        print(line)
        return

    # Try to split into haiku
    haiku = split_haiku(words, syllables)
    if haiku:
        for line_out in haiku:
            print(line_out)
    else:
        print(line)

if __name__ == '__main__':
    main()

