def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n_str, k_str = data[0], data[1]
    n = list(n_str)
    k = int(k_str)
    length = len(n)

    # Greedy algorithm with priority queue
    for i in range(length):
        if k <= 0:
            break
        # Find the maximum digit from i+1 to end
        max_idx = i
        max_digit = n[i]
        for j in range(i+1, length):
            if n[j] > max_digit:
                max_digit = n[j]
                max_idx = j
        # If found a larger digit, swap
        if max_idx != i:
            # Check for leading zero
            if i == 0 and n[max_idx] == '0':
                continue
            n[i], n[max_idx] = n[max_idx], n[i]
            k -= 1

    # Handle remaining swaps (parity adjustment)
    if k > 0 and k % 2 == 1:
        # Try to swap two equal digits
        swapped = False
        for i in range(length):
            for j in range(i+1, length):
                if n[i] == n[j]:
                    swapped = True
                    break
            if swapped:
                break
        if not swapped and length >= 2:
            # Swap last two digits (safe from leading zero)
            n[-1], n[-2] = n[-2], n[-1]

