import sys

def get_hand(i, n, s):
    """Get favorite hand for player i using modulo indexing."""
    return s[i % n]

def match_winner(a_hand, b_hand):
    """Return winner's hand in RPS match, or a_hand if draw."""
    if a_hand == b_hand:
        return a_hand
    if (a_hand == 'R' and b_hand == 'S') or (a_hand == 'P' and b_hand == 'R') or (a_hand == 'S' and b_hand == 'P'):
        return a_hand
    return b_hand

def tournament_winner(l, r, n, s):
    """Recursively compute winner's hand for players [l, r-1]."""
    if r - l == 1:
        return get_hand(l, n, s)
    m = (l + r) // 2
    a_hand = tournament_winner(l, m, n, s)
    b_hand = tournament_winner(m, r, n, s)
    return match_winner(a_hand, b_hand)

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    k = int(data[1])
    s = data[2]
    total_players = 1 << k  # 2^k
    result = tournament_winner(0, total_players, n, s)
    print(result)

if __name__ == "__main__":
    main()

