import sys
sys.setrecursionlimit(1000000)

class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        x_root = self.find(x)
        y_root = self.find(y)
        if x_root == y_root:
            return False
        if self.rank[x_root] < self.rank[y_root]:
            self.parent[x_root] = y_root
        elif self.rank[x_root] > self.rank[y_root]:
            self.parent[y_root] = x_root
        else:
            self.parent[y_root] = x_root
            self.rank[x_root] += 1
        return True

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    idx = 0
    N = int(data[idx]); idx += 1
    M = int(data[idx]); idx += 1

    dsu = DSU(N)
    edges = []

    for _ in range(M):
        u = int(data[idx]); idx += 1
        op = data[idx]; idx += 1
        v = int(data[idx]); idx += 1

        if op == '=':
            dsu.union(u, v)
        else:
            edges.append((u, v))

    # Build adjacency list for each component
    comp_adj = {}
    for u, v in edges:
        comp_u = dsu.find(u)
        comp_v = dsu.find(v)
        if comp_u == comp_v:
            print("inconsistent")
            return

        if comp_u not in comp_adj:
            comp_adj[comp_u] = []
        if comp_v not in comp_adj:
            comp_adj[comp_v] = []

        comp_adj[comp_u].append(comp_v)
        comp_adj[comp_v].append(comp_u)

    # Check for cycles using DFS
    visited = {}
    def dfs(node, color):
        if node in visited:
            return visited[node] == color
        visited[node] = color
        for neighbor in comp_adj.get(node, []):
            if not dfs(neighbor, 1 - color):
                return False
        return True

    for comp in comp_adj:
        if comp not in visited:
            if not dfs(comp, 0):
                print("inconsistent")
                return

    print("consistent")

if __name__ == "__main__":
    main()

