            dsu.union(u, v)
        else:
            edges.append((u, v))

    # Build adjacency list for each component
    comp_adj = {}
    for u, v in edges:
        comp_u = dsu.find(u)
        comp_v = dsu.find(v)
        if comp_u == comp_v:
            print("inconsistent")
            return

        if comp_u not in comp_adj:
            comp_adj[comp_u] = []
        if comp_v not in comp_adj:
            comp_adj[comp_v] = []

        comp_adj[comp_u].append(comp_v)
        comp_adj[comp_v].append(comp_u)

    # Check for cycles using DFS
    visited = {}
    def dfs(node, color):
        if node in visited:
            return visited[node] == color
        visited[node] = color
        for neighbor in comp_adj.get(node, []):
            if not dfs(neighbor, 1 - color):
                return False
        return True

    for comp in comp_adj:
        if comp not in visited:
            if not dfs(comp, 0):
                print("inconsistent")
                return

    print("consistent")

